-- 全国城市覆盖房源：在现有 501 条基础上新增 499 条，合计 1000 条，覆盖 sys_region 全部 391 个城市
-- 生成时间：2026-11-14；使用前请确保已导入 house.sql / houseconfig.sql / demo_house_data.sql
-- 可重复执行：会先删除本文件生成的 1000511~1001009 号房源及其关联数据
SET NAMES utf8mb4;
START TRANSACTION;
DELETE FROM tag_house WHERE house_id BETWEEN 1000511 AND 1001009;
DELETE FROM house_status WHERE house_id BETWEEN 1000511 AND 1001009;
DELETE FROM city_house WHERE house_id BETWEEN 1000511 AND 1001009;
DELETE FROM house WHERE id BETWEEN 1000511 AND 1001009;
UPDATE house SET intro=REPLACE(intro, CONCAT('（', region_name), '（') WHERE id BETWEEN 1000511 AND 1001009;
COMMIT;
SELECT COUNT(*) AS total_houses FROM house;
SELECT COUNT(DISTINCT city_id) AS covered_cities FROM house;
